def _integer(value: object, name: str, *, minimum: int | None = None) -> int:
    if not isinstance(value, int) or isinstance(value, bool):
        raise ValueError(f"{name} must be an integer")
    if minimum is not None and value < minimum:
        raise ValueError(f"{name} is below its allowed range")
    return value


def _text(value: object, name: str, *, nullable: bool = False) -> str | None:
    if value is None and nullable:
        return None
    if not isinstance(value, str):
        raise ValueError(f"{name} must be a string")
    return value


def _exact(arguments: dict[str, Any], expected: set[str]) -> None:
    if set(arguments) != expected:
        raise ValueError("worker operation has missing or unknown arguments")


def _validate_arguments(operation: str, arguments: dict[str, Any]) -> None:
    no_arguments = {"close", "get_state", "supported_core_registers", "halt", "resume", "step", "reset", "reset_and_halt", "recover", "release_reset"}
    if operation in no_arguments:
        _exact(arguments, set())
        return
    if operation in {"open", "connect_under_reset"}:
        expected = {"board", "unique_id", "target", "server_timeouts", "protocol", "connect_mode", "pack_path", "pack_sha256", "pdsc_device", "frequency_hz"}
        _exact(arguments, expected)
        if arguments["board"] is not None and not isinstance(arguments["board"], dict):
            raise ValueError("board must be an object or null")
        for name in ("unique_id", "target", "protocol", "connect_mode", "pack_path", "pack_sha256", "pdsc_device"):
            _text(arguments[name], name, nullable=True)
        if arguments["frequency_hz"] is not None:
            _integer(arguments["frequency_hz"], "frequency_hz", minimum=1)
        if not isinstance(arguments["server_timeouts"], dict):
            raise ValueError("server_timeouts must be an object")
        return
    if operation == "read_memory":
        _exact(arguments, {"address", "width_bits"})
        _integer(arguments["address"], "address", minimum=0)
        if _integer(arguments["width_bits"], "width_bits") not in {8, 16, 32}:
            raise ValueError("width_bits is unsupported")
        return
    if operation == "read_memory_block":
        _exact(arguments, {"address", "length"})
        _integer(arguments["address"], "address", minimum=0)
        _integer(arguments["length"], "length", minimum=1)
        return
    if operation == "write_memory":
        _exact(arguments, {"address", "value", "width_bits"})
        _integer(arguments["address"], "address", minimum=0)
        value = _integer(arguments["value"], "value", minimum=0)
        width_bits = _integer(arguments["width_bits"], "width_bits")
        if width_bits not in {8, 16, 32}:
            raise ValueError("width_bits is unsupported")
        if value > (1 << width_bits) - 1:
            raise ValueError("value exceeded requested memory width")
        if value is not None:
            raise ValueError("worker void operation returned data")
        return None
    if operation == "get_state":
        if not isinstance(value, str) or not value:
            raise ValueError("worker state result was invalid")
        return value
    if operation == "read_memory":
        if arguments is None:
            raise ValueError("worker memory result lacked request facts")
        _, width_bits = _memory_arguments(arguments, write=False)
        result = _strict_int(value, operation)
        if result < 0 or result > (1 << width_bits) - 1:
            raise ValueError("worker memory result exceeded its requested width")
        return result
    if operation == "read_core_register":
        return _strict_int(value, operation)
    if operation == "read_memory_block":
        if arguments is None:
            raise ValueError("worker memory block result lacked request facts")
        length = arguments.get("length")
        if not isinstance(length, int) or isinstance(length, bool) or length < 1:
            raise ValueError("worker memory block request length was invalid")
        if not isinstance(value, list) or len(value) != length:
            raise ValueError("worker memory block length did not match the request")
        result = [_strict_int(item, "memory block item") for item in value]
        if any(item < 0 or item > 255 for item in result):
            raise ValueError("worker memory block item exceeded byte range")
        return result
    if operation == "supported_core_registers":
        if not isinstance(value, list) or any(not isinstance(item, str) for item in value):
            raise ValueError("worker register-list result was invalid")
        return value
    if operation == "supports_recovery":
        if not isinstance(value, bool):
            raise ValueError("worker recovery capability result was invalid")
        return value
    if operation in {"open", "connect_under_reset"}:
        required = {
            "board_name",
            "probe_description",
            "probe_family",
            "probe_uid",
            "live_part_number",
            "route_used",
            "target_override",
            "runtime_token",
        }
        if not isinstance(value, dict) or set(value) != required:
            raise ValueError("worker session metadata schema was invalid")
        for key in {"board_name", "probe_description", "probe_family"}:
            if not isinstance(value[key], str):
                raise ValueError(f"worker metadata field {key} was invalid")
        for key in {"route_used", "runtime_token"}:
            if not isinstance(value[key], str) or not value[key]:
                raise ValueError(f"worker metadata field {key} was invalid")
        for key in {"probe_uid", "live_part_number", "target_override"}:
            if value[key] is not None and not isinstance(value[key], str):
                raise ValueError(f"worker metadata field {key} was invalid")
        return value
    raise ValueError("worker returned an unallowlisted operation")


def _positive_timeout(value: object, name: str) -> float:
    if isinstance(value, bool) or not isinstance(value, int | float):
        raise ValueError(f"{name} must be a finite positive number")
    numeric = float(value)
    if not math.isfinite(numeric) or numeric <= 0:
        raise ValueError(f"{name} must be a finite positive number")
    return numeric


def _timeout(timeout: float | None) -> float:
    return _positive_timeout(
        DEFAULT_EXTERNAL_COMMAND_TIMEOUT_SECONDS if timeout is None else timeout,
            raise RuntimeError(
                f"Board '{board_id}' connection changed while disconnecting; retry disconnect."
            )
