            "flash_firmware",
            normalized_args,
            outcome_kind=ToolOutcome.SUCCESS,
            error_code=None,
            duration_ms=_duration_ms(started),
            details={"target_state": state},
            board_id=board_id,
            session=runtime,
        )
        return (
            f"Flashed {flashed} via {session_metadata(active_handle).route_used}; "
            f"target left {state}."
        )


